async function loadFoods(){try{const base=await (await fetch('assets/foods.json')).json();S.customFoods=[];if(sb&&session){const {data}=await sb.from('custom_foods').select('*').eq('user_id',session.user.id).order('created_at',{ascending:false});S.customFoods=data||[]}const custom=S.customFoods.map(x=>({name:x.name,cat:x.category,portion:x.portion_label,kcal:+x.kcal,p:+x.protein_g,c:+x.carbs_g,f:+x.fat_g,origin:'Meu alimento',approx:false,_customId:x.id}));S.foods=[...custom,...base]}catch(e){console.error(e);S.foods=[]}}
