async function loadDayData(){
 S.ex=new Set();S.activitiesDone=new Set();S.mealsDone=new Set();S.water=0;S.beverages=[];S.beyondMl=0;S.steps=0;S.dayStatus='in_progress';const date=S.currentDate||localDate();
 const [{data:ex},{data:al},{data:ml},{data:dl},{data:bl},{data:bv}]=await Promise.all([sb.from('exercise_logs').select('*').eq('user_id',session.user.id).eq('log_date',date),sb.from('activity_logs').select('*').eq('user_id',session.user.id).eq('log_date',date),sb.from('meal_logs').select('*').eq('user_id',session.user.id).eq('log_date',date),sb.from('daily_logs').select('*').eq('user_id',session.user.id).eq('log_date',date).maybeSingle(),sb.from('body_logs').select('*').eq('user_id',session.user.id).eq('log_date',date).maybeSingle(),sb.from('beverage_logs').select('*').eq('user_id',session.user.id).eq('log_date',date).order('created_at')]);
 S.ex=new Set((ex||[]).filter(x=>x.completed).map(x=>x.exercise_key));S.activitiesDone=new Set((al||[]).filter(x=>x.completed).map(x=>x.activity_key));S.mealsDone=new Set((ml||[]).filter(x=>x.completed).map(x=>x.meal_key));S.beverages=bv||[];const detailedHydration=S.beverages.filter(x=>x.hydration_counts).reduce((a,x)=>a+(+x.volume_ml||0),0)/1000;S.water=S.beverages.length?detailedHydration:(+dl?.water_l||0);S.beyondMl=S.beverages.filter(x=>!x.hydration_counts).reduce((a,x)=>a+(+x.volume_ml||0),0);S.steps=+bl?.steps||0;S.dayStatus=dl?.status||'in_progress';
 for(const x of (ml||[])){if(x.deleted)continue;if(x.foods&&Array.isArray(x.foods)){const meal={key:x.meal_key,name:x.meal_name,time:(x.meal_time||'').slice(0,5),target:Math.round(+x.kcal||0),protein:+x.protein_g||0,carbs:+x.carbs_g||0,fat:+x.fat_g||0,foodItems:normalizeFoodItems(x.foods),foods:normalizeFoodItems(x.foods).map(foodLabel)};const ix=S.plan.meals.findIndex(m=>m.key===x.meal_key);if(ix>=0)S.plan.meals[ix]={...S.plan.meals[ix],...meal};else S.plan.meals.push(meal)}}
 try{const {data:wp}=await sb.from('workout_plans').select('exercises,activities').eq('user_id',session.user.id).eq('plan_date',date).maybeSingle();if(wp?.exercises?.length)S.plan.exercises=wp.exercises;if(Array.isArray(wp?.activities))S.plan.activities=wp.activities}catch(e){console.warn('Plano de treino diário não carregado',e)}
 S.plan.meals.forEach(enrichMeal);
}
