function renderEx(){$('#exerciseList').innerHTML=S.plan.exercises.map((e,i)=>`<article class="item exerciseCard ${S.ex.has(e.key)?'done':''}"><div class="exerciseInfo"><span>${e.group||'EXERCÍCIO'} • ${formatDate(S.currentDate)}</span><h3>${e.name}</h3><p><b>Músculos:</b> ${e.muscles||e.group||'—'}</p><p>${e.scheme||`${e.sets||3} × ${e.reps||'8–12'}`} • descanso ${e.rest||90}s${e.targetLoad?` • alvo ${e.targetLoad} kg`:''}</p><div class="exerciseActions"><button class="soft mini" onclick="openEditExercise('${e.key}')">EDITAR</button><button class="soft mini" onclick="moveExercise('${e.key}',-1)" ${i===0?'disabled':''}>↑</button><button class="soft mini" onclick="moveExercise('${e.key}',1)" ${i===S.plan.exercises.length-1?'disabled':''}>↓</button></div></div><div class="loadBox"><input id="load_${e.key}" type="number" step="0.5" placeholder="kg"><button class="soft" onclick="saveLoad('${e.key}')">SALVAR CARGA</button><button class="check" aria-label="Concluir exercício" onclick="togEx('${e.key}')">${S.ex.has(e.key)?'✓':'○'}</button></div></article>`).join('')+`<button class="soft full addExerciseBtn" onclick="openEditExercise()">+ ADICIONAR EXERCÍCIO</button>`}
function renderActivities(){const planned=Array.isArray(S.plan.activities)?S.plan.activities:[],routine=normalizeActivities(S.p.other_activities||[]);const p=$('#plannedActivities'),r=$('#routineActivitiesList');if(p)p.innerHTML=planned.length?planned.map(a=>`<article class="item activityCard ${S.activitiesDone.has(a.key)?'done':''}"><div><span>ATIVIDADE PLANEJADA • ${formatDate(S.currentDate)}</span><h3>${a.name}</h3><p>${a.duration_min?`${a.duration_min} min`:''}${a.notes?` • ${a.notes}`:''}</p></div><button class="check" onclick="togActivity('${a.key}')">${S.activitiesDone.has(a.key)?'✓':'○'}</button></article>`).join(''):'<p class="emptyActivities">Nenhuma atividade extra planejada para este dia.</p>';if(r)r.innerHTML=routine.length?routine.map(a=>`<span>${activityLabel(a)}</span>`).join(''):'<span>Nenhuma atividade além da musculação cadastrada.</span>'}
async function togActivity(key){const a=(S.plan.activities||[]).find(x=>x.key===key);if(!a)return;S.activitiesDone.has(key)?S.activitiesDone.delete(key):S.activitiesDone.add(key);const {data,error}=await sb.from('activity_logs').upsert({user_id:session.user.id,log_date:S.currentDate,activity_key:key,activity_name:a.name,duration_min:a.duration_min||null,completed:S.activitiesDone.has(key),notes:a.notes||null,source:a.source||'plan'},{onConflict:'user_id,log_date,activity_key'}).select().single();if(error)return toast(error.message);S.activityHistory=S.activityHistory.filter(x=>!(x.log_date===S.currentDate&&x.activity_key===key));if(data)S.activityHistory.unshift(data);await persistDaily();renderActivities();renderHist();renderMonthly();progress()}
