async function saveActivitiesManager(){const arr=normalizeActivities(S.activityDraft.filter(a=>String(a.name||'').trim()));const text=arr.map(activityLabel).join('; ');await updateProfileFields({other_activities:arr,other_activities_text:text||null});S.p.other_activities=arr;S.p.other_activities_text=text||null;closeActivitiesManager();renderActivities();renderProfile();toast('Atividades da rotina atualizadas ✓')}
function openEditExercise(key=null){S.editingExerciseKey=key;const e=key?S.plan.exercises.find(x=>x.key===key):null;$('#editExerciseTitle').textContent=e?'Editar exercício':'Adicionar exercício';$('#exName').value=e?.name||'';$('#exSets').value=e?.sets||Number((e?.scheme?.match(/\d+/)||[3])[0]);$('#exReps').value=e?.reps||(e?.scheme?.split('×')[1]||'8–12').trim();$('#exRest').value=e?.rest||90;$('#exTarget').value=e?.targetLoad||'';renderExerciseLibrary();$('#editExerciseModal').classList.add('open')}
